def get_users(page: int, page_size: int) -> tuple[list[dict], int]:
    all_users = sorted(store.get_all_users(), key=lambda x: x["id"])
    total = len(all_users)
    start = (page - 1) * page_size
    end = start + page_size
    return all_users[start:end], total

